CREATE OR REPLACE FUNCTION generate_performance_alert()
RETURNS TRIGGER AS $$
DECLARE
    v_existing_alert RECORD;
    v_panel_hub uuid;
BEGIN
    -- Only process on INSERT
    IF TG_OP = 'INSERT' THEN
        -- Extract annual degradation from efficiency_profile JSONB
        DECLARE
            v_anndegrate numeric;
        BEGIN
            v_anndegrate := (NEW.efficiency_profile->'degradation'->>'anndegrate')::numeric;
        EXCEPTION WHEN OTHERS THEN
            RETURN NEW;
        END;

        -- Check if degradation exceeds 0.7% threshold
        IF v_anndegrate > 0.7 THEN
            -- Get the hubregistry (plant) for this panel
            SELECT hubregistry INTO v_panel_hub FROM panel WHERE panemark = NEW.solmodref;

            -- Check if a similar alert already exists for this device and incident
            SELECT * INTO v_existing_alert 
            FROM alerts 
            WHERE deviceref = NEW.solmodref 
              AND incidentref = NEW.perfregistry
              AND alertstat = 'Critical';

            IF FOUND THEN
                -- Update existing alert - increment count
                UPDATE alerts 
                SET alertcnt = COALESCE(alertcnt, 0) + 1,
                    alertmoment = NEW.perfmoment
                WHERE deviceref = NEW.solmodref 
                  AND incidentref = NEW.perfregistry
                  AND alertstat = 'Critical';
            ELSE
                -- Insert new Critical Performance Alert
                INSERT INTO alerts (alertreg, compreg, deviceref, incidentref, alertmoment, alertstat, alertcnt, maintprior, replaceprior, optpotential)
                VALUES (
                    gen_random_uuid()::text,
                    COALESCE(v_panel_hub, NEW.solmodref::uuid),
                    NEW.solmodref,
                    NEW.perfregistry,
                    NEW.perfmoment,
                    'Critical',
                    1,
                    'High',
                    'High',
                    'Medium'
                );
            END IF;
        END IF;
    END IF;

    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

