CREATE OR REPLACE FUNCTION generate_performance_alert() RETURNS TRIGGER AS $$
DECLARE
    v_anndegrate NUMERIC;
    v_panel_hub UUID;
BEGIN
    IF TG_OP = 'INSERT' THEN
        BEGIN
